FLAC__StreamDecoderWriteStatus write_callback(const FLAC__StreamDecoder *decoder, const FLAC__Frame *frame, const int32_t *const buffer[], void *client_data) {
    PrivateData *data = (PrivateData *)client_data;
    data->frame = *frame;
    data->buffer = buffer;
    copy_buffer(data);
    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}

FLAC__StreamDecoderWriteStatus write_callback(const FLAC__StreamDecoder *decoder, const FLAC__Frame *frame, const int32_t * const buffer[], void *client_data) {
    PrivateData *private_data = (PrivateData*)client_data;
    private_data->frame = frame;
    private_data->buffer = buffer;
    private_data->position = frame->header.number.serial_number;

    copy_buffer(private_data);

    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}

FLAC__StreamDecoderWriteStatus flac_write_callback(
    const FLAC__StreamDecoder *decoder,
    const FLAC__Frame *frame,
    const int32_t * const buffer[],
    void *client_data)
{
    (void)decoder; // unused parameter

    struct PrivateData *data = (struct PrivateData *)client_data;
    data->frame = frame;
    data->buffer = buffer;
    data->position = frame->header.number.sample_number;

    copy_buffer(data);
    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}

FLAC__StreamDecoderWriteStatus flac_write_callback(
    const FLAC__StreamDecoder *decoder,
    const FLAC__Frame *frame,
    const int32_t *const buffer[],
    void *client_data
) {
    (void)decoder;

    flac_private_data *data = (flac_private_data*)client_data;
    data->frame = frame;
    data->buffer = buffer;
    data->position = frame->header.number.serial;
    copy_buffer(data);
    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}

FLAC__StreamDecoderWriteStatus write_callback(const FLAC__StreamDecoder *decoder, const FLAC__Frame *frame, const int32_t * const buffer[], void *client_data) {
    struct private_data *data = (struct private_data*)client_data;
    data->frame = frame;
    data->buffer = buffer;
    data->position = 0;
    copy_buffer(data);
    return FLAC__STREAM_DECODER_WRITE_STATUS_CONTINUE;
}
